\end{eqnarray}
where \eqref{eq_u8} is by the definition of the event $\hat{E}^c_\alpha$ in \eqref{eq_n77}.

We also have (by, e.g., Inequality (27) in \cite{mangoubi2022private}) that

\begin{equation}\label{eq_u9}
