\end{equation}

Therefore, plugging in \eqref{eq_u9} into \eqref{eq_u8}, we get that, whenever the event  $\hat{E}^c_\alpha$ occurs,
\begin{equation}\label{eq_u10}
    \|U_k(t_0) -U_k(0)\|_F \leq \frac{4\sqrt{t_0}(\sqrt{d} + \alpha)}{\sigma_k - \sigma_{k+1}}.
